#!/usr/bin/env python3
"""Normalize log files of mixed encodings into a single clean UTF-8 file."""
import os
import re

LOG_DIR = "/app/logs"
OUTPUT_FILE = "/app/normalized_output.txt"

MOJIBAKE_HINTS = ("Ã", "Â", "â€", "â€", "ð", "Ð", "Ñ", "å", "ä", "æ")
HEX_ESC_RE = re.compile(rb"\\x([0-9a-fA-F]{2})")


def fix_hex_escapes(raw: bytes) -> bytes:
    """Convert literal \\xNN escape sequences into actual bytes."""
    if b"\\x" not in raw:
        return raw
    return HEX_ESC_RE.sub(lambda m: bytes([int(m.group(1), 16)]), raw)


def repair_mojibake(text: str) -> str:
    """Fix text that was UTF-8 decoded as a single-byte encoding (possibly repeatedly)."""
    for _ in range(4):
        if not any(h in text for h in MOJIBAKE_HINTS):
            break
        fixed = None
        for enc in ("latin-1", "cp1252"):
            try:
                candidate = text.encode(enc).decode("utf-8")
            except (UnicodeEncodeError, UnicodeDecodeError):
                continue
            fixed = candidate
            break
        if fixed is None or fixed == text:
            break
        text = fixed
    return text


def decode_line(raw: bytes) -> str:
    """Decode a single raw line (bytes) into clean text."""
    raw = raw.replace(b"\xef\xbb\xbf", b"")  # strip BOM anywhere on the line
    raw = fix_hex_escapes(raw)

    text = None
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        for enc in ("cp1252", "cp932", "latin-1"):
            try:
                text = raw.decode(enc)
                break
            except (UnicodeDecodeError, LookupError):
                continue
    if text is None:
        # Last resort: drop undecodable bytes safely
        text = raw.decode("utf-8", errors="ignore")

    text = repair_mojibake(text)
    # Remove any residual non-characters / lone surrogates safely
    return text


def normalize_file(path: str) -> list:
    with open(path, "rb") as fh:
        data = fh.read()
    # Normalize all line endings to \n, then split
    data = data.replace(b"\r\n", b"\n").replace(b"\r", b"\n")
    lines = []
    for raw_line in data.split(b"\n"):
        line = decode_line(raw_line).strip()
        if line:
            lines.append(line)
    return lines


def main():
    all_lines = []
    per_file = {}
    files = sorted(f for f in os.listdir(LOG_DIR) if f.endswith(".log"))
    for fname in files:
        lines = normalize_file(os.path.join(LOG_DIR, fname))
        per_file[fname] = len(lines)
        all_lines.extend(lines)

    with open(OUTPUT_FILE, "w", encoding="utf-8", newline="\n") as out:
        for line in all_lines:
            out.write(line + "\n")

    print("Normalization complete.")
    for fname in files:
        print(f"  {fname}: {per_file[fname]} lines")
    print(f"Total lines written: {len(all_lines)}")


if __name__ == "__main__":
    main()
